actions.script:
                import groovy.json.JsonOutput

                String compName = targetComponent.trim().toLowerCase().replaceAll("[^a-z0-9-]", "")
                String relPath = screenPath.trim()

                if (relPath.startsWith("component://")) {
                    relPath = relPath.replace("component://" + compName + "/screen/", "")
                }
                if (relPath.endsWith(".xml")) {
                    relPath = relPath.substring(0, relPath.length() - 4)
                }
                if (relPath.startsWith("/")) {
                    relPath = relPath.substring(1)
                }

                // Ensure component sub-folder is present (e.g. nursinghome/PatientManagement)
                if (!relPath.startsWith(compName + "/") && !relPath.contains("/")) {
                    relPath = "${compName}/${relPath}"
                }

                String fullArtifactUri = "component://${compName}/screen/${relPath}.xml"
                String physicalFilePath = "runtime/component/${compName}/screen/${relPath}.xml"

                File targetFile = new File(physicalFilePath)
                if (targetFile.exists()) {
                    ec.message.addError("Screen file already exists at: ${physicalFilePath}")
                    return
                }

                targetFile.getParentFile().mkdirs()

                String targetEditor = (editorType && editorType.trim().length() > 0) ? editorType.trim() : "AgiScreenEditor"
                String displayTitle = title ?: relPath.substring(relPath.lastIndexOf('/') + 1)
                String rootContainerId = relPath.replaceAll("[^a-zA-Z0-9_]", "_") + "_root"
                String cleanComponentName = relPath.substring(relPath.lastIndexOf('/') + 1)

                String qvtAssetPath = null
                String qvtPhysicalPath = null

                if ("AgiComponentEditor".equals(targetEditor)) {
                    int lastSlashIdx = relPath.lastIndexOf('/')
                    String dirPrefix = (lastSlashIdx != -1) ? relPath.substring(0, lastSlashIdx + 1) : ""

                    qvtAssetPath = "component://${compName}/screen/${dirPrefix}assets/${cleanComponentName}.qvt.js"
                    qvtPhysicalPath = "runtime/component/${compName}/screen/${dirPrefix}assets/${cleanComponentName}.qvt.js"

                    File qvtFile = new File(qvtPhysicalPath)
                    qvtFile.getParentFile().mkdirs()

                    String qvtContent = """(function () {
    const ${cleanComponentName} = {
        name: '${cleanComponentName}',
        template: `
            <div class="q-pa-md bg-slate-900 text-white rounded-borders">
                <div class="text-h6 text-primary">${displayTitle}</div>
                <div class="text-caption text-grey-4">Custom Component Viewport</div>
            </div>
        `,
        data() {
            return {
                title: '${displayTitle}'
            };
        }
    };

    window.${cleanComponentName} = ${cleanComponentName};
    if (!window.AgiComponents) window.AgiComponents = {};
    window.AgiComponents['${cleanComponentName}'] = ${cleanComponentName};
})();
"""
                    qvtFile.text = qvtContent
                    ec.logger.info("📄 [MCP /create-screen] Created companion QVT asset at ${qvtPhysicalPath}")
                }

                String scriptIncludeTag = qvtAssetPath ? "\n    <script location=\"${qvtAssetPath}\"/>\n" : ""

                String xmlContent = """<?xml version="1.0" encoding="UTF-8"?>
<screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
        xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/xml-screen-3.xsd"
        require-authentication="true"
        editor="${targetEditor}">
${scriptIncludeTag}
    <widgets>
        <container id="${rootContainerId}">
            <label text="${displayTitle}" type="h4"/>
        </container>
    </widgets>
</screen>
"""
                targetFile.text = xmlContent
                ec.logger.info("📄 [MCP /create-screen] Created XML screen shell at ${physicalFilePath}")

                // Auto-register AgiArtifact record
                def enumCheck = ec.entity.find("moqui.basic.Enumeration").condition("enumId", "AatXmlScreen").one()
                String typeEnumId = enumCheck ? "AatXmlScreen" : null

                def artifactVal = ec.entity.find("org.moqui.ai.AgiArtifact")
                        .condition("artifactPath", fullArtifactUri)
                        .one()

                if (!artifactVal) {
                    artifactVal = ec.entity.makeValue("org.moqui.ai.AgiArtifact")
                    artifactVal.set("artifactPath", fullArtifactUri)
                    artifactVal.set("artifactTypeEnumId", typeEnumId)
                    artifactVal.set("artifactStatusEnumId", "AasDraft")
                    artifactVal.set("totalIntentCount", 1)
                    artifactVal.set("completedIntentCount", 0)
                    artifactVal.set("completionPercentage", 0.0)
                    artifactVal.setSequencedIdPrimary()
                    artifactVal.create()
                }

                // Initial Seed of WorkspaceBuffer AST
                ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.parse#XmlToTree")
                    .parameter("artifactUri", fullArtifactUri)
                    .call()

                String cleanParentId = (parentWorkEffortId != null && parentWorkEffortId.trim().length() > 0) 
                    ? parentWorkEffortId.trim() 
                    : null

                String safeMariaId = org.moqui.ide.ScreenEditorServices.generateMariaId(sourceReferenceId, targetMariaId)
                ec.logger.info("📦 [MCP /create#Screen] safeMariaId: ${safeMariaId}, length: ${safeMariaId.length()} ")

                Map weResult = ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
                    workEffortName: "Screen Intent: " + displayTitle,
                    parentWorkEffortId: cleanParentId,
                    agiArtifactId: artifactVal.agiArtifactId,
                    sourceReferenceId: fullArtifactUri,
                    workEffortTypeEnumId: "WetIntent",
                    targetMariaId: safeMariaId 
                ]).call()

                context.artifactUri = fullArtifactUri
                context.qvtAssetUri = qvtAssetPath
                context.agiArtifactId = artifactVal.agiArtifactId
                context.workEffortId = weResult.workEffortId

String compName = targetComponent.trim().toLowerCase().replaceAll("[^a-z0-9-]", "")

def normalizeUri = { String rawUri ->
    String cleaned = rawUri.trim()
    if (!cleaned.endsWith(".xml")) cleaned += ".xml"
    if (cleaned.startsWith("component://")) return cleaned

    if (cleaned.startsWith("screen/")) {
        return "component://${compName}/${cleaned}"
    } else {
        return "component://${compName}/screen/${cleaned}"
    }
}

String srcUri = normalizeUri(sourceArtifactUri)
String tgtUri = normalizeUri(targetArtifactUri)

String srcPhysical = "runtime/component/" + srcUri.replace("component://", "")
String tgtPhysical = "runtime/component/" + tgtUri.replace("component://", "")

ec.logger.info("🚚 [MCP /move-artifact] Resolving srcPhysical: ${srcPhysical} -> tgtPhysical: ${tgtPhysical}")

File srcFile = new File(srcPhysical)
if (!srcFile.exists()) {
    ec.message.addError("Source file does not exist on disk: ${srcPhysical}")
    return
}

File tgtFile = new File(tgtPhysical)
tgtFile.getParentFile().mkdirs()

boolean moved = srcFile.renameTo(tgtFile)
if (!moved) {
    tgtFile.text = srcFile.text
    srcFile.delete()
}
ec.logger.info("🚚 [MCP /move-artifact] Successfully relocated file on disk to: ${tgtPhysical}")

// Move companion QVT asset if present
String srcQvtPhysical = srcPhysical.replace(".xml", ".qvt.js")
int lastSlashIdx = srcQvtPhysical.lastIndexOf('/')
if (lastSlashIdx != -1) {
    String srcQvtDir = srcQvtPhysical.substring(0, lastSlashIdx)
    String fileName = srcQvtPhysical.substring(lastSlashIdx + 1)
    File srcQvtFile = new File("${srcQvtDir}/assets/${fileName}")

    if (srcQvtFile.exists()) {
        String tgtQvtPhysical = tgtPhysical.replace(".xml", ".qvt.js")
        int tgtSlashIdx = tgtQvtPhysical.lastIndexOf('/')
        String tgtQvtDir = tgtQvtPhysical.substring(0, tgtSlashIdx)
        File tgtQvtFile = new File("${tgtQvtDir}/assets/${fileName}")
        tgtQvtFile.getParentFile().mkdirs()

        srcQvtFile.renameTo(tgtQvtFile)
        ec.logger.info("🚚 [MCP /move-artifact] Relocated companion QVT asset to: ${tgtQvtFile.path}")
    }
}

// Cascade update all database references
def art = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", srcUri).one()
if (art) {
    art.artifactPath = tgtUri
    art.update()
    context.agiArtifactId = art.agiArtifactId
}

def buffers = ec.entity.find("org.moqui.ai.WorkspaceBuffer").condition("artifactUri", srcUri).list()
buffers.each { buf ->
    buf.artifactUri = tgtUri
    buf.update()
}

def workEfforts = ec.entity.find("mantle.work.effort.WorkEffort").condition("sourceReferenceId", srcUri).list()
workEfforts.each { we ->
    we.sourceReferenceId = tgtUri
    we.update()
}

context.artifactUri = tgtUri

                String compName = targetComponent.trim().toLowerCase().replaceAll("[^a-z0-9-]", "")
                String rawUri = artifactUri ?: screenPath

                if (!rawUri || rawUri.trim().isEmpty()) {
                    ec.message.addError("Either artifactUri or screenPath must be provided to attach a QVT asset.")
                    return
                }

                String cleaned = rawUri.trim()
                if (!cleaned.endsWith(".xml")) cleaned += ".xml"

                String srcUri
                if (cleaned.startsWith("component://")) {
                    srcUri = cleaned
                } else if (cleaned.startsWith("screen/")) {
                    srcUri = "component://${compName}/${cleaned}"
                } else {
                    srcUri = "component://${compName}/screen/${cleaned}"
                }

                String relPath = srcUri.replace("component://", "")
                String physicalPath = "runtime/component/" + relPath

                File xmlFile = new File(physicalPath)
                if (!xmlFile.exists()) {
                    ec.message.addError("Screen XML file does not exist on disk: ${physicalPath}")
                    return
                }

                String cleanCompName = xmlFile.name.replace(".xml", "")
                int lastSlashIdx = physicalPath.lastIndexOf('/')
                String dirPath = (lastSlashIdx != -1) ? physicalPath.substring(0, lastSlashIdx) : ""

                String qvtPhysical = "${dirPath}/assets/${cleanCompName}.qvt.js"
                String qvtUri = srcUri.substring(0, srcUri.lastIndexOf('/')) + "/assets/${cleanCompName}.qvt.js"

                File qvtFile = new File(qvtPhysical)
                if (!qvtFile.exists()) {
                    qvtFile.getParentFile().mkdirs()
                    String qvtContent = """(function () {
    const ${cleanCompName} = {
        name: '${cleanCompName}',
        template: `
            <div class="q-pa-md bg-slate-900 text-white rounded-borders">
                <div class="text-h6 text-primary">${cleanCompName} Component</div>
                <div class="text-caption text-grey-4">Custom Component Viewport</div>
            </div>
        `,
        data() {
            return {
                title: '${cleanCompName}'
            };
        }
    };

    window.${cleanCompName} = ${cleanCompName};
    if (!window.AgiComponents) window.AgiComponents = {};
    window.AgiComponents['${cleanCompName}'] = ${cleanCompName};
})();
"""
                    qvtFile.text = qvtContent
                    ec.logger.info("📄 [MCP /attach-qvt-asset] Created companion QVT file at ${qvtPhysical}")
                }

                String xmlText = xmlFile.text
                if (!xmlText.contains("AgiComponentEditor")) {
                    xmlText = xmlText.replace("editor=\"AgiScreenEditor\"", "editor=\"AgiComponentEditor\"")
                    if (!xmlText.contains("editor=")) {
                        xmlText = xmlText.replace("<screen ", "<screen editor=\"AgiComponentEditor\" ")
                    }
                }

                String scriptTag = "<script location=\"${qvtUri}\"/>"
                if (!xmlText.contains(scriptTag)) {
                    xmlText = xmlText.replace("require-authentication=\"true\">", "require-authentication=\"true\">\n    " + scriptTag)
                }

                xmlFile.text = xmlText
                ec.logger.info("✏️ [MCP /attach-qvt-asset] Updated ${physicalPath} to include ${scriptTag}")

                // Re-sync AST
                ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.parse#XmlToTree")
                    .parameter("artifactUri", srcUri)
                    .call()

                def art = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", srcUri).one()
                if (art) {
                    def parentWe = ec.entity.find("mantle.work.effort.WorkEffort")
                            .condition("agiArtifactId", art.agiArtifactId)
                            .condition("workEffortTypeEnumId", "WetIntent")
                            .one()

                    ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
                        workEffortName: "Attached QVT Asset: " + cleanCompName,
                        parentWorkEffortId: parentWe?.workEffortId,
                        agiArtifactId: art.agiArtifactId,
                        sourceReferenceId: qvtUri,
                        workEffortTypeEnumId: "WetIntent"
                    ]).call()
                }

                context.qvtAssetUri = qvtUri
                context.artifactUri = srcUri

import groovy.json.JsonSlurper
import groovy.json.JsonOutput

// 1. Fetch current AST layout tree from WorkspaceBuffer
Map bufResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.get#WorkspaceBuffer")
    .parameter("artifactUri", artifactUri)
    .call()

if (!bufResult?.metaJsonBuffer) {
    ec.message.addError("Could not retrieve active WorkspaceBuffer AST for artifact: ${artifactUri}")
    return
}

Map layoutTree = new JsonSlurper().parseText(bufResult.metaJsonBuffer) as Map
String newId = containerId ?: "${containerType}-${System.currentTimeMillis()}"

// 2. Build the new AST node
Map newNode = [
    _moquiTag: containerType,
    '@type': "m-${containerType}",
    id: newId,
    mariaId: "maria_${newId.replaceAll('[^a-zA-Z0-9_]', '_')}",
    children: []
]
if (styleClass) newNode.style = styleClass
if (conditionScript) newNode.condition = conditionScript

// 3. Helper to locate target parent node in AST
def findTargetNode
findTargetNode = { Map node ->
    if (!node) return null
    if (parentContainerId) {
        if (node.id == parentContainerId || node.mariaId == parentContainerId || node.name == parentContainerId) {
            return node
        }
    }
    List searchChildren = []
    if (node.children instanceof List) searchChildren.addAll(node.children)
    if (node.widgets instanceof List) searchChildren.addAll(node.widgets)

    for (def child in searchChildren) {
        if (child instanceof Map) {
            def match = findTargetNode((Map) child)
            if (match != null) return match
        }
    }
    return null
}

Map targetNode = parentContainerId ? findTargetNode(layoutTree) : null
if (!targetNode) {
    // Fallback to top-level widgets or root node
    targetNode = layoutTree
}

if (targetNode.children == null) targetNode.children = []
targetNode.children.add(newNode)

// 4. Save updated AST buffer and compile back to physical XML
String updatedJson = JsonOutput.toJson(layoutTree)

ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
    .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson])
    .call()

ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml")
    .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson])
    .call()

ec.logger.info("📦 [MCP /add-container] Injected <${containerType} id=\"${newId}\"> into AST for ${artifactUri}")

context.artifactUri = artifactUri
context.createdContainerId = newId

def art = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactUri).one()
if (art) {
    def parentWe = ec.entity.find("mantle.work.effort.WorkEffort")
            .condition("agiArtifactId", art.agiArtifactId)
            .condition("workEffortTypeEnumId", "WetIntent")
            .one()

    String safeMariaId = org.moqui.ide.ScreenEditorServices.generateMariaId(sourceReferenceId, targetMariaId)
    ec.logger.info("📦 [MCP /add-container] safeMariaId: ${safeMariaId}, length: ${safeMariaId.length()} ")

    ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
        workEffortName: "Added Container (${containerType}): ${newId}",
        parentWorkEffortId: parentWe?.workEffortId,
        agiArtifactId: art.agiArtifactId,
        sourceReferenceId: artifactUri,
        workEffortTypeEnumId: "WetIntent",
        targetMariaId: safeMariaId
    ]).call()
}

import groovy.json.JsonSlurper
import groovy.json.JsonOutput

String name = subscreenName
String location = subscreenLocation

if (!location) {
    String parentDir = artifactUri.substring(0, artifactUri.lastIndexOf('.'))
    location = "${parentDir}/${name}.xml"
}

String title = menuTitle ?: name.replaceAll("([a-z])([A-Z])", '$1 $2')
boolean setAsDefault = isDefault || (defaultSubscreen && defaultSubscreen.toString().contains(name))

// 1. Fetch current AST layout tree
Map bufResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.get#WorkspaceBuffer")
    .parameter("artifactUri", artifactUri)
    .call()

if (!bufResult?.metaJsonBuffer) {
    ec.message.addError("Parent screen URI (${artifactUri}) could not load into WorkspaceBuffer.")
    return
}

Map layoutTree = new JsonSlurper().parseText(bufResult.metaJsonBuffer) as Map

// 2. Mutate subscreens map inside the AST
if (layoutTree.subscreens == null || !(layoutTree.subscreens instanceof Map)) {
    layoutTree.subscreens = [
        _moquiTag: "subscreens",
        defaultItem: setAsDefault ? name : "",
        children: []
    ]
}

if (setAsDefault) {
    layoutTree.subscreens.defaultItem = name
}

List subItems = layoutTree.subscreens.children ?: []
def existingItem = subItems.find { it.name == name }

if (existingItem) {
    existingItem.location = location
    existingItem.menuTitle = title
} else {
    subItems.add([
        _moquiTag: "subscreens-item",
        "@type": "m-subscreens-item",
        name: name,
        location: location,
        menuTitle: title
    ])
}
layoutTree.subscreens.children = subItems

// 3. Ensure navigation and body viewports exist in the widget tree
def findOrCreateWidget = { String tag, String idVal ->
    def findTag
    findTag = { Map node ->
        if (!node) return null
        if (node._moquiTag == tag || node['@type'] == "m-${tag}") return node
        for (child in (node.children ?: [])) {
            if (child instanceof Map) {
                def m = findTag(child)
                if (m) return m
            }
        }
        return null
    }
    if (!findTag(layoutTree)) {
        if (layoutTree.children == null) layoutTree.children = []
        layoutTree.children.add([
            _moquiTag: tag,
            '@type': "m-${tag}",
            id: idVal
        ])
    }
}

findOrCreateWidget("subscreens-tabs", "nursinghome-nav-tabs")
findOrCreateWidget("subscreens-active", "nursinghome-body-viewport")

// 4. Save and compile
String updatedJson = JsonOutput.toJson(layoutTree)

ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
    .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson])
    .call()

ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml")
    .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson])
    .call()

ec.logger.info("🔗 [bind#Subscreen] Bound subscreen [${name}] to [${artifactUri}] in AST.")
context.artifactUri = artifactUri

String rawPath = artifactUri ?: screenPath ?: "AgiWorkspace"
def resourceReference = null

try {
    // 1. Direct location lookup if full component:// URI is supplied
    if (rawPath.startsWith("component://")) {
        resourceReference = ec.resource.getLocationReference(rawPath)
    } 

    // 2. Fallback candidate resolution logic
    if (!resourceReference || !resourceReference.exists) {
        String componentName = "nursinghome"
        String fileName = rawPath

        if (rawPath.contains("/")) {
            def parts = rawPath.split("/")
            componentName = parts[0]
            fileName = parts[1]
        }

        String xmlLoc = "component://${componentName}/screen/${componentName}/${fileName}.xml"
        resourceReference = ec.resource.getLocationReference(xmlLoc)

        if (!resourceReference || !resourceReference.exists) {
            String qvtLoc = "component://${componentName}/screen/${componentName}/assets/${fileName}.qvt.js"
            resourceReference = ec.resource.getLocationReference(qvtLoc)
        }
    }

    if (resourceReference && resourceReference.exists) {
        context.rawXmlContent = resourceReference.getText()
        context.fileLocation = resourceReference.location
        ec.logger.info("⚡ [REST /getRawXml] Retrieved asset at: [${resourceReference.location}]")
    } else {
        context.rawXmlContent = ""
        context.fileLocation = null
    }
} catch (Exception ex) {
    ec.logger.error("Failed to execute dynamic resource extraction", ex)
    context.rawXmlContent = ""
    context.fileLocation = null
}

import groovy.json.JsonSlurper
import groovy.json.JsonOutput

// 1. Fetch current AST layout tree
Map bufResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.get#WorkspaceBuffer")
    .parameter("artifactUri", artifactUri)
    .call()

if (!bufResult?.metaJsonBuffer) {
    ec.message.addError("Screen XML could not load into WorkspaceBuffer at ${artifactUri}")
    return
}

Map layoutTree = new JsonSlurper().parseText(bufResult.metaJsonBuffer) as Map

// 2. Build Action Node Map
Map actionNode = [
    _moquiTag: actionType,
    '@type': "m-${actionType}"
]
if (actionType == "entity-find") {
    actionNode["entity-name"] = entityName
    actionNode.list = listName
    if (filterField && filterValue) {
        actionNode.children = [[
            _moquiTag: "econdition",
            "field-name": filterField,
            value: filterValue
        ]]
    }
}

if (layoutTree.actions == null || !(layoutTree.actions instanceof Map)) {
    layoutTree.actions = [
        _moquiTag: "actions",
        children: []
    ]
}

List actionItems = layoutTree.actions.children ?: []
actionItems.add(actionNode)
layoutTree.actions.children = actionItems

// 3. Save and compile
String updatedJson = JsonOutput.toJson(layoutTree)

ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
    .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson])
    .call()

ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml")
    .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson])
    .call()

ec.logger.info("⚡ [add#ActionToScreen] Injected ${actionType} into AST for ${artifactUri}")
context.artifactUri = artifactUri

import groovy.json.JsonSlurper import groovy.json.JsonOutput
// 1. Hydrate AST from WorkspaceBuffer Map bufResult = ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.get#WorkspaceBuffer") .parameter("artifactUri", artifactUri) .call()
if (!bufResult?.metaJsonBuffer) { ec.message.addError("Could not load WorkspaceBuffer for: ${artifactUri}") return }
Map layoutTree = new JsonSlurper().parseText(bufResult.metaJsonBuffer) as Map String baseName = artifactUri.replaceAll(/.*\/|\.xml$/, "") String titleText = headerTitle ?: baseName.replaceAll(/([a-z])([A-Z])/, '$1 $2')
// 2. Build Header Container Node Map headerContainer = [ _moquiTag: "container", "@type": "m-container", id: "${baseName}-header-banner", style: headerStyle, children: [ [ _moquiTag: "label", "@type": "m-label", type: "h4", text: titleText ], [ _moquiTag: "subscreens-tabs", "@type": "m-subscreens-tabs", id: "${baseName}-nav-tabs" ] ] ]
// 3. Build Content Viewport Node Map contentContainer = [ _moquiTag: "container", "@type": "m-container", id: "${baseName}-content-viewport", style: contentStyle, children: [ [ _moquiTag: "subscreens-active", "@type": "m-subscreens-active", id: "${baseName}-active-body" ] ] ]
// 4. Overwrite widgets root children with clean two-section layout layoutTree.children = [headerContainer, contentContainer]
// 5. Persist AST to WorkspaceBuffer & compile XML to disk String updatedJson = JsonOutput.toJson(layoutTree)
ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer") .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson]) .call()
ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml") .parameters([artifactUri: artifactUri, metaJsonBuffer: updatedJson]) .call()
ec.logger.info("📐 [scaffold#SubscreenHub] Successfully scaffolded Header + Content layout in ${artifactUri}") context.artifactUri = artifactUri

import org.moqui.resource.ResourceReference
String safeName = archetypeName.replaceAll("[^a-zA-Z0-9_-]", "") String templateLocation = "component://agi-ide/archetype/screen/${safeName}.xml"
ResourceReference rr = ec.resource.getLocationReference(templateLocation) if (rr != null && rr.exists) { context.archetypeName = safeName context.templateXml = rr.getText() context.status = "SUCCESS" context.usageGuidelines = """ 1. Adhere strictly to xml-screen-3.xsd. 2. Never wrap <hidden/> or <display/> in <container name="...">. 3. For lookups, ensure default-menu-include="false" and standalone="true" on <screen>. 4. Return selections using declarative parameter maps rather than inline JavaScript. """ ec.logger.info("📐 [MCP:get#ScreenArchetype] Archetype dispatched to AI: ${templateLocation}") } else { context.archetypeName = safeName context.templateXml = "" context.status = "NOT_FOUND" context.usageGuidelines = "Archetype not found. Available archetypes: lookup-modal" ec.logger.warn("⚠️ [MCP:get#ScreenArchetype] Archetype not found: ${templateLocation}") }
